 static struct sk_buff *virtio_transport_build_skb(void *opaque)
 {
 	struct virtio_vsock_hdr *pkt_hdr;
 	struct sk_buff *pkt = opaque;
 	struct af_vsockmon_hdr *hdr;
 	struct sk_buff *skb;
 	size_t payload_len;

